export async function retry<T>(task: (attempt: number) => Promise<T>, maxAttempts: number): Promise<T> {
  if (!Number.isSafeInteger(maxAttempts) || maxAttempts < 1) {
    throw new RangeError("maxAttempts must be a positive safe integer")
  }
  let lastError: unknown
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try { return await task(attempt) } catch (error) {
      lastError = error
    }
  }
  throw lastError
}

export function normalizeHeaders(entries: readonly (readonly [string, string])[]): Record<string, string> {
  const combined = new Map<string, string[]>()
  for (const [rawName, rawValue] of entries) {
    const name = rawName.trim().toLowerCase()
    const value = rawValue.trim()
    const values = combined.get(name)
    if (values === undefined) combined.set(name, [value])
    else values.push(value)
  }
  const result: Record<string, string> = {}
  for (const [name, values] of combined) {
    Object.defineProperty(result, name, {
      value: values.join(", "),
      writable: true,
      enumerable: true,
      configurable: true,
    })
  }
  return result
}

