export function takeCodePoints(text: string, limit: number) {
  if (!Number.isSafeInteger(limit) || limit < 0) {
    throw new RangeError("limit must be a non-negative safe integer")
  }
  if (limit === 0) return ""

  let end = 0
  let count = 0
  while (end < text.length && count < limit) {
    const unit = text.charCodeAt(end)
    const next = end + 1 < text.length ? text.charCodeAt(end + 1) : NaN
    const isSurrogatePair =
      unit >= 0xd800 && unit <= 0xdbff && next >= 0xdc00 && next <= 0xdfff
    end += isSurrogatePair ? 2 : 1
    count += 1
  }
  return text.slice(0, end)
}

