export type Job = { id: string; dependsOn: readonly string[] }

export function orderJobs(jobs: readonly Job[]): string[] {
  const indexById = new Map<string, number>()
  jobs.forEach((job, index) => indexById.set(job.id, index))

  const remainingDeps: number[] = jobs.map((job) => new Set(job.dependsOn).size)
  const dependents: number[][] = jobs.map(() => [])
  jobs.forEach((job, index) => {
    for (const depId of new Set(job.dependsOn)) {
      const depIndex = indexById.get(depId)
      if (depIndex !== undefined && depIndex !== index) dependents[depIndex].push(index)
    }
  })

  const ready: number[] = []
  remainingDeps.forEach((count, index) => {
    if (count === 0) ready.push(index)
  })

  const order: string[] = []
  while (ready.length > 0) {
    let pick = 0
    for (let i = 1; i < ready.length; i++) {
      if (ready[i] < ready[pick]) pick = i
    }
    const [index] = ready.splice(pick, 1)
    order.push(jobs[index].id)
    for (const dependent of dependents[index]) {
      remainingDeps[dependent] -= 1
      if (remainingDeps[dependent] === 0) ready.push(dependent)
    }
  }

  if (order.length !== jobs.length) throw new Error("dependency cycle detected")
  return order
}

