export function splitLines(chunks: readonly string[]): string[] {
  const lines: string[] = []
  let buffered = ""

  for (const chunk of chunks) {
    buffered += chunk

    let start = 0
    for (;;) {
      const nl = buffered.indexOf("\n", start)
      if (nl === -1) break
      // A CR immediately before the LF is part of a CRLF terminator,
      // even when the pair is split across chunks; a lone CR is content.
      const end = nl > start && buffered[nl - 1] === "\r" ? nl - 1 : nl
      lines.push(buffered.slice(start, end))
      start = nl + 1
    }

    buffered = buffered.slice(start)
  }

  // Preserve a final unterminated line, but a trailing terminator
  // (or empty input) adds no extra empty line.
  if (buffered.length > 0) lines.push(buffered)

  return lines
}

export function splitLines(chunks: readonly string[]): string[] {
  const text = chunks.join("")
  const lines: string[] = []
  let start = 0

  for (let i = 0; i < text.length; i++) {
    if (text[i] !== "\n") continue
    // A CR immediately before an LF is part of the line terminator, not content.
    const end = i > 0 && text[i - 1] === "\r" ? i - 1 : i
    lines.push(text.slice(start, end))
    start = i + 1
  }

  // Preserve a final unterminated line; a trailing terminator adds nothing.
  if (start < text.length) lines.push(text.slice(start))

  return lines
}

