export type Adjustment = { sku: string; delta: number }
export function applyAdjustments(stock: Record<string, number>, changes: readonly Adjustment[]): void {
  const pending = new Map<string, number>()
  for (const change of changes) {
    const { sku, delta } = change
    if (!Object.hasOwn(stock, sku)) throw new Error("Unknown stock key")
    if (!Number.isSafeInteger(delta)) throw new Error("Delta must be a safe integer")
    const next = (pending.get(sku) ?? stock[sku]) + delta
    if (!Number.isSafeInteger(next) || next < 0) throw new Error("Insufficient stock")
    pending.set(sku, next)
  }
  for (const [sku, quantity] of pending) stock[sku] = quantity
}

export type Adjustment = { sku: string; delta: number }
export function applyAdjustments(stock: Record<string, number>, changes: readonly Adjustment[]): void {
  const staged = new Map<string, number>()
  for (const change of changes) {
    if (!Object.hasOwn(stock, change.sku)) throw new Error("Unknown stock key")
    if (!Number.isSafeInteger(change.delta)) throw new Error("Delta must be a safe integer")
    const base = staged.has(change.sku) ? staged.get(change.sku)! : stock[change.sku]
    const result = base + change.delta
    if (!Number.isSafeInteger(result)) throw new Error("Invalid stock quantity")
    if (result < 0) throw new Error("Insufficient stock")
    staged.set(change.sku, result)
  }
  for (const [sku, quantity] of staged) stock[sku] = quantity
}

export function redact(text: string, secrets: readonly string[]): string {
  const active = secrets.filter((secret) => secret.length > 0)
  let result = ""
  let i = 0
  while (i < text.length) {
    let match = ""
    for (const secret of active) {
      if (secret.length > match.length && text.startsWith(secret, i)) {
        match = secret
      }
    }
    if (match.length > 0) {
      result += "[REDACTED]"
      i += match.length
    } else {
      result += text[i]
      i += 1
    }
  }
  return result
}

